// @pit: {"label": "Update durable docs, changelog, README pin, and package version to 0.36.4"}
async ({ workspace: { edit, search, read } }, p: { doc: string; cl: string }) => {
  const [readme, pkg, lock, cl] = await Promise.all([
    search("pit@v0.36.3", { path: "README.md" }),
    search('"version": "0.36.3"', { path: "package.json" }),
    read("package-lock.json", { limit: 12 }),
    search("## [Unreleased]", { path: "CHANGELOG.md" }),
  ]);
  const lines: string[] = lock.content.split("\n").filter((l: string) => l.includes('"version": "0.36.3"'));
  const changes = lines.map((l) => ({ kind: "replace" as const, start: l.split("|")[0] as `${number}:${string}`, content: l.split("|").slice(1).join("|").replace("0.36.3", "0.36.4") }));
  if (changes.length !== 2) throw new Error(`lock lines: ${lines.length}`);
  const r = readme.matches[0];
  const out = [];
  out.push(await edit("docs/durable.md", { revision: "dfxy-9U4EQ_P", changes: [{ kind: "insertAfter", anchor: "85:xEkle", content: p.doc }] }));
  out.push(await edit("CHANGELOG.md", { revision: cl.matches[0].revision, changes: [{ kind: "insertAfter", anchor: cl.matches[0].anchor, content: p.cl }] }));
  out.push(await edit("README.md", { revision: r.revision, changes: [{ kind: "replace", start: r.anchor, content: r.text.replace("v0.36.3", "v0.36.4") }] }));
  out.push(await edit("package.json", { revision: pkg.matches[0].revision, changes: [{ kind: "replace", start: pkg.matches[0].anchor, content: pkg.matches[0].text.replace("0.36.3", "0.36.4") }] }));
  out.push(await edit("package-lock.json", { revision: lock.revision, changes: [changes[0]!, changes[1]!] }));
  return out.map((o: any) => `${o.file} ${o.applied}`);
}
